package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.math.NumberUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class BooleanUtils_toBoolean_TriageGen0Test {

    @Test
    public void testToBoolean_TrueCases() {
        // Test the interned optimization
        assertTrue(BooleanUtils.toBoolean("true"));

        // Test case 4: lowercase 't' variations
        assertTrue(BooleanUtils.toBoolean("true"));
        assertTrue(BooleanUtils.toBoolean("trUE"));
        assertTrue(BooleanUtils.toBoolean("trUe"));
        assertTrue(BooleanUtils.toBoolean("tRUe"));
        assertTrue(BooleanUtils.toBoolean("TRuE"));
        assertTrue(BooleanUtils.toBoolean("tRuE"));
        assertTrue(BooleanUtils.toBoolean("trUE"));

        // Test case 4: uppercase 'T' variations
        assertTrue(BooleanUtils.toBoolean("TRUE"));
        assertTrue(BooleanUtils.toBoolean("TrUE"));
        assertTrue(BooleanUtils.toBoolean("TRue"));
        assertTrue(BooleanUtils.toBoolean("T r u e".replace(" ", ""))); // "TRUE"
        assertTrue(BooleanUtils.toBoolean("T r u e".replace(" ", "") == null ? "" : "TRUE")); 

        // Specifically targeting the branches in case 4
        assertTrue(BooleanUtils.toBoolean("tRuE"));
        assertTrue(BooleanUtils.toBoolean("TrUe"));
        assertTrue(BooleanUtils.toBoolean("TRuE"));
        assertTrue(BooleanUtils.toBoolean("TrUE"));
        assertTrue(BooleanUtils.toBoolean("T r u e".replace(" ", "") == null ? "" : "TRUE"));

        // Re-verifying exact logic for case 4
        assertTrue(BooleanUtils.toBoolean("t r u e".replace(" ", ""))); // not possible with current code, checking logic
        assertTrue(BooleanUtils.toBoolean("true"));
        assertTrue(BooleanUtils.toBoolean("trUE"));
        assertTrue(BooleanUtils.toBoolean("tRUe"));
        assertTrue(BooleanUtils.toBoolean("trUe"));
        assertTrue(BooleanUtils.toBoolean("TRUE"));
        assertTrue(BooleanUtils.toBoolean("TrUE"));
        assertTrue(BooleanUtils.toBoolean("T r u e".replace(" ", "") == null ? "" : "TRUE"));
    }












}

