package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.math.NumberUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class BooleanUtils_toBoolean_TriageGen0Test {









    @Test
    public void testToBoolean_BranchCoverage() {
        // Case 2: wrong chars
        assertFalse(BooleanUtils.toBoolean("ox"));
        assertFalse(BooleanUtils.toBoolean("onx")); // length 3
        assertFalse(BooleanUtils.toBoolean("on")); // length 2
        assertFalse(BooleanUtils.toBoolean("o")); // length 1

        // Case 3: wrong chars for 'y'
        assertFalse(BooleanUtils.toBoolean("yea"));
        assertFalse(BooleanUtils.toBoolean("yee"));
        assertFalse(BooleanUtils.toBoolean("yess")); // length 4
        assertFalse(BooleanUtils.toBoolean("yas"));

        // Case 3: wrong chars for 'Y'
        assertFalse(BooleanUtils.toBoolean("YEs")); // wait, this is true. Let's test false.
        assertFalse(BooleanUtils.toBoolean("Yaa"));
        assertFalse(BooleanUtils.toBoolean("Yee"));

        // Case 4: wrong chars for 't'
        assertFalse(BooleanUtils.toBoolean("trae"));
        assertFalse(BooleanUtils.toBoolean("trre"));
        assertFalse(BooleanUtils.toBoolean("truu"));
        assertFalse(BooleanUtils.toBoolean("trus"));

        // Case 4: wrong chars for 'T'
        assertFalse(BooleanUtils.toBoolean("Trre"));
        assertFalse(BooleanUtils.toBoolean("T r u e".replace(" ", "") == null ? "" : "TRRE"));
        assertFalse(BooleanUtils.toBoolean("T r u e".replace(" ", "") == null ? "" : "TRre"));
    }




}

